import * as React from "react";

export type TicketTearDashedIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function TicketTearDashedIcon({ size = 20, ...props }: TicketTearDashedIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="4" y="6" width="16" height="12" rx="1.5" /><path d="M12 6.5v2M12 10.5v2M12 14.5v2" />
    </svg>
  );
}
